import numpy as np
def read(p):
    L=open(p).read().split("\n"); n=int(L[0])
    els=[];xyz=[]
    for l in L[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append(list(map(float,t[1:4])))
    return els,np.array(xyz)
els,c = read("full.xyz")
frag1=set(range(0,72)); frag2=set(range(72,98)); frag3=set(range(98,124)); frag4=set(range(124,150))
for a,b,nm in ((frag1,frag2,"lig-cp1"),(frag1,frag3,"lig-cp2"),(frag1,frag4,"lig-cp3"),(frag2,frag3,"cp1-cp2"),(frag2,frag4,"cp1-cp3"),(frag3,frag4,"cp2-cp3")):
    pairs=sorted((np.linalg.norm(c[i]-c[j]),i,j,els[i],els[j]) for i in a for j in b)[:3]
    print(nm,["%.2f %s%d-%s%d"%(p[0],p[3],p[1],p[4],p[2]) for p in pairs])
# angles at Si
def ang(i,j,k):
    v1=c[i]-c[j]; v2=c[k]-c[j]
    return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
print("Zn1-Si-Zn2",ang(72,31,98),"Zn1-Si-N18",ang(72,31,18),"Zn2-Si-N18",ang(98,31,18))
print("Zn1-Si-N2",ang(72,31,2),"Zn2-Si-N2",ang(98,31,2))
